package com.theseusoft.service;
import com.theseusoft.dto.*; import com.theseusoft.entity.ContactMessage; import com.theseusoft.repository.ContactMessageRepository; import java.util.List; import org.springframework.stereotype.Service;
@Service public class ContactMessageService { private final ContactMessageRepository repository; public ContactMessageService(ContactMessageRepository repository){this.repository=repository;} public ContactMessageResponse create(ContactMessageRequest r){var e=new ContactMessage();e.setName(r.name());e.setEmail(r.email());e.setCompany(r.company());e.setMessage(r.message());return map(repository.save(e));} public List<ContactMessageResponse> findAll(){return repository.findAll().stream().map(this::map).toList();} private ContactMessageResponse map(ContactMessage e){return new ContactMessageResponse(e.getId(),e.getName(),e.getEmail(),e.getCompany(),e.getMessage(),e.getCreatedAt());} }
